/* From Uiverse.io by Javierrocadev - Tags: card, star, rotate, hover effect, trophy, winner */
.__UIV_SCOPE__ .container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  font-size: 5em;
  font-weight: 900;
  color: #e10600;
  position: relative;
  transition: all 1s ease;
  text-align: center;
}

.__UIV_SCOPE__ .container__star {
  transition: all .7s ease-in-out;
}

.__UIV_SCOPE__ .first {
  position: absolute;
  top: 20px;
  left: 50px;
  transition: all .7s ease-in-out;
}

.__UIV_SCOPE__ .svg-icon {
  position: absolute;
  fill: #e94822;
  z-index: 1;
}

.__UIV_SCOPE__ .star-eight {
  background: #efd510;
  width: 150px;
  height: 150px;
  position: relative;
  text-align: center;
  animation: rot 3s  infinite;
}

.__UIV_SCOPE__ .star-eight::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  height: 150px;
  width: 150px;
  background: #efd510;
  transform: rotate(135deg);
}

.__UIV_SCOPE__ .container:hover .container__star {
  transform: rotateX(70deg) translateY(250px);
  box-shadow: 0px 0px 120px -100px #e4e727;
}

.__UIV_SCOPE__ .container:hover .svg-icon {
  animation: grow 1s linear infinite;
}

@keyframes rot {
  0% {
    transform: rotate(0deg);
  }

  50% {
    transform: rotate(340deg);
  }

  100% {
    transform: rotate(0deg);
  }
}

@keyframes grow {
  0% {
    transform: rotate(0deg);
  }

  25% {
    transform: rotate(-5deg);
  }

  75% {
    transform: rotate(5deg);
  }

  100% {
    transform: scale(1) rotate(0deg);
  }
}
